package com.gameaggregator.versionservice.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.versionservice.api.VersionDtos.*;import com.gameaggregator.versionservice.domain.GameVersion;import com.gameaggregator.versionservice.infrastructure.GameVersionRepository;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class VersionService{final GameVersionRepository repo;final ObjectMapper json;public VersionService(GameVersionRepository r,ObjectMapper j){repo=r;json=j;}public GameVersion create(Create r){if(repo.existsByGameIdAndSemanticVersion(r.gameId(),r.semanticVersion()))throw new IllegalArgumentException("Semantic version already exists for game");return repo.save(new GameVersion(r.gameId(),r.semanticVersion(),r.changelog(),write(r.compatibility()),write(r.supportedPlatforms()),r.minimumClientVersion()));}public List<GameVersion> list(UUID gameId){return gameId==null?repo.findAll():repo.findAllByGameId(gameId);}public GameVersion get(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("VERSION_NOT_FOUND","Version was not found"));}public GameVersion update(UUID id,Update r){var v=get(id);if(!"DRAFT".equals(v.status))throw new IllegalStateException("Only draft version can be edited");v.changelog=r.changelog();v.compatibilityJson=write(r.compatibility());v.supportedPlatformsJson=write(r.supportedPlatforms());v.minimumClientVersion=r.minimumClientVersion();return v;}public GameVersion status(UUID id,Status r){var v=get(id);v.status=r.status();return v;}private String write(Object o){try{return json.writeValueAsString(o==null?Map.of():o);}catch(Exception e){throw new IllegalArgumentException("Invalid version metadata",e);}}}